statements.select:
SELECT COMPANY_CD , UP_DEPT_NM , DEPT_NM , USER_NM , SUM_1 , SUM_2 , CASE WHEN SUM_1 != 0 AND SUM_2 != 0 THEN (SUM_2/CONVERT(numeric(18,3),SUM_1)) * 100 ELSE 0 END AS SUM_3 , SUM_4 , SUM_2 + SUM_4 AS SUM_5 , SUM_6 , SUM_7 , SUM_8 , CASE WHEN SUM_7 != 0 AND SUM_8 != 0 THEN (SUM_8/CONVERT(numeric(18,3),SUM_7)) * 100 ELSE 0 END AS SUM_9 , SUM_10 , SUM_11 , CASE WHEN SUM_10 != 0 AND SUM_11 != 0 THEN (SUM_11/CONVERT(numeric(18,3),SUM_10)) * 100 ELSE 0 END AS SUM_12 FROM ( SELECT COMPANY_CD , (SELECT UP_DEPT_CD FROM T_DEPARTMENT WHERE DEPT_CD = DBO.fn_get_user_to_dept_cd(A.USER_CD)) AS UP_DEPT_CD , (SELECT DEPT_NM FROM T_DEPARTMENT WHERE DEPT_CD = (SELECT UP_DEPT_CD FROM T_DEPARTMENT WHERE DEPT_CD = DBO.fn_get_user_to_dept_cd(A.USER_CD))) AS UP_DEPT_NM , A.DEPT_CD , A.DEPT_NM , DBO.fn_get_user_nm(A.USER_CD) AS USER_NM
, (SELECT COUNT(SA_CD) FROM T_SALES_ACTIVITY WHERE PLAN_YN = 'Y' AND A.BASE_YM <= SUBSTRING(SA_EDATE, 1, 6) AND A.BASE_YM >= SUBSTRING(SA_SDATE, 1, 6) AND USER_CD = A.USER_CD AND USE_YN = 'Y'
AND SA_TYPE = #sa_type#
) AS SUM_1
, (SELECT COUNT(SA_CD) FROM T_SALES_ACTIVITY WHERE PLAN_YN = 'Y' AND A.BASE_YM <= SUBSTRING(SA_EDATE, 1, 6) AND A.BASE_YM >= SUBSTRING(SA_SDATE, 1, 6) AND USER_CD = A.USER_CD AND SA_BODY IS NOT NULL AND USE_YN = 'Y'
AND SA_TYPE = #sa_type#
) AS SUM_2
, (SELECT COUNT(SA_CD) FROM T_SALES_ACTIVITY WHERE PLAN_YN = 'N' AND A.BASE_YM <= SUBSTRING(SA_EDATE, 1, 6) AND A.BASE_YM >= SUBSTRING(SA_SDATE, 1, 6) AND USER_CD = A.USER_CD AND SA_BODY IS NOT NULL AND USE_YN = 'Y'
AND SA_TYPE = #sa_type#
) AS SUM_4
, (SELECT SUM(KM_QTY) FROM T_SA_KM_SUMMARY WHERE BASE_YM = A.BASE_YM AND USER_CD = A.USER_CD) AS SUM_6 , (SELECT SUM(KM_H_QTY) FROM T_SA_KM_SUMMARY WHERE BASE_YM = A.BASE_YM AND USER_CD = A.USER_CD) AS SUM_7 , (SELECT COUNT(*) FROM ( SELECT DISTINCT KM_CD FROM T_SA_KEYMAN WHERE KM_CD IN (SELECT KM_CD FROM T_KEYMAN WHERE CUST_CD IN (SELECT CUST_CD FROM T_CUSTOMER WHERE USER_CD = A.USER_CD)) AND SA_CD IN (SELECT SA_CD FROM T_SALES_ACTIVITY WHERE SA_CD IN (SELECT SA_CD FROM T_SA_COMMENT WHERE (SA_COMMENT IS NOT NULL AND SA_COMMENT != '') GROUP BY SA_CD) AND USE_YN = 'Y'
AND SA_TYPE = #sa_type#
)) A) AS SUM_8 , (SELECT COUNT(SA_CD) FROM T_SALES_ACTIVITY WHERE A.BASE_YM <= SUBSTRING(SA_EDATE, 1, 6) AND A.BASE_YM >= SUBSTRING(SA_SDATE, 1, 6) AND SA_BODY IS NOT NULL AND USER_CD = A.USER_CD AND CMT_YN = 'Y' AND USE_YN = 'Y'
AND SA_TYPE = #sa_type#
) AS SUM_10 , (SELECT COUNT(SA_CD) FROM (SELECT SA_CD FROM T_SA_COMMENT WHERE (SA_COMMENT IS NOT NULL AND SA_COMMENT != '') AND SA_CD IN (SELECT SA_CD FROM T_SALES_ACTIVITY WHERE A.BASE_YM <= SUBSTRING(SA_EDATE, 1, 6) AND A.BASE_YM >= SUBSTRING(SA_SDATE, 1, 6) AND SA_BODY IS NOT NULL AND USER_CD = A.USER_CD AND CMT_YN = 'Y' AND USE_YN = 'Y'
AND SA_TYPE = #sa_type#
) GROUP BY SA_CD) AA) AS SUM_11 FROM ( SELECT T.COMPANY_CD , T.USER_CD , DBO.FN_GET_USER_TO_DEPT_CD(T.USER_CD) AS DEPT_CD , DBO.FN_GET_USER_TO_DEPT_NM(T.USER_CD) AS DEPT_NM , #base_ym# AS BASE_YM FROM T_USER T LEFT OUTER JOIN T_DEPARTMENT AS D ON T.COMPANY_CD = D.COMPANY_CD AND T.DEPT_CD = D.DEPT_CD
WHERE T.COMPANY_CD = #company_cd# AND T.SA_YN = 'Y'
AND T.DEPT_CD = #deptGroup#
AND D.UP_DEPT_CD = #bizGroup# AND T.DEPT_CD IS NOT NULL
AND T.USER_CD = #user_cd#
) A WHERE DBO.fn_get_user_to_dept_cd(A.USER_CD) IS NOT NULL ) B ORDER BY UP_DEPT_CD ASC, DEPT_CD ASC
